pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // set up block conditions: set block.timestamp to 100 and block.number to a multiple of 15
        vm.warp(100);
        vm.roll(15);

        address alice = address(0xABCD);
        vm.deal(alice, 20 ether);

        // first call: succeeds in both versions
        vm.prank(alice);
        bool ok1;
        try c.fall{value: 10 ether}() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);

        // second call: same block.timestamp, so reference reverts (strict > fails), buggy accepts (>= passes)
        vm.prank(alice);
        bool ok2;
        try c.fall{value: 10 ether}() { ok2 = true; } catch { ok2 = false; }

        // The reference version will have ok2 = false (revert), the buggy version will have ok2 = true.
        // We assert that the second call reverts, which holds for the reference but fails for the buggy version.
        assertTrue(!ok2);
    }
}

